SINA_SMART["histo1-muscle"] = {"lecture":"histo1-muscle","title":"Muscle tissue","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-muscle:e0","text":"Muscle: contractile cells with actin and myosin; from mesoderm.","topic":"Muscle tissue","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e1","text":"Skeletal: cylindrical, multinucleated, peripheral nuclei, striated, voluntary.","topic":"Skeletal muscle","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e2","text":"Wrappings: endomysium (fibre), perimysium (fascicle), epimysium (muscle).","topic":"Skeletal muscle","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e5","text":"Triad = T tubule + two terminal cisternae (skeletal).","topic":"Skeletal muscle","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e3","text":"Sarcomere = Z to Z; I band actin only, A band myosin length, H zone myosin only.","topic":"The sarcomere","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e4","text":"Contraction: I band and H zone shorten; A band unchanged.","topic":"The sarcomere","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e6","text":"Cardiac: branched, 1-2 central nuclei, intercalated discs (gap junctions + desmosomes).","topic":"Cardiac and smooth muscle","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e7","text":"Smooth: fusiform, one central nucleus, no striations, dense bodies.","topic":"Cardiac and smooth muscle","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-muscle:e8","text":"Regeneration: skeletal via satellite cells; cardiac very poor (scar); smooth good.","topic":"Cardiac and smooth muscle","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"o1gnww":"a","qere58":"a","t9ht2o":"a","1eth56b":"a","11x9ydm":"a","tvayrb":"a","1phwcsl":"a","k5jx55":"a","imsbr0":"a","w9y29f":"a","h1hn9o":"a","1i4ujp2":"a","1oixcky":"a","f2s6wy":"a","41u591":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-muscle:e0":{"s":0,"u":["Muscle: contractile cells with actin and myosin; from mesoderm.","Muscle tissue is made of elongated contractile cells (muscle fibres) rich in actin (thin) and myosin (thick) filaments; it derives from mesoderm ."],"dp":[]},"histo1-muscle:e1":{"s":1,"u":["Skeletal: cylindrical, multinucleated, peripheral nuclei, striated, voluntary.","Long cylindrical , multinucleated fibres with nuclei at the periphery under the sarcolemma; clear cross-striations ; voluntary ."],"dp":[]},"histo1-muscle:e2":{"s":1,"u":["Wrappings: endomysium (fibre), perimysium (fascicle), epimysium (muscle).","Connective tissue wrappings: endomysium around each fibre, perimysium around each fascicle, epimysium around the whole muscle."],"dp":[]},"histo1-muscle:e5":{"s":1,"u":["Triad = T tubule + two terminal cisternae (skeletal).","Invaginations of the sarcolemma ( T tubules ) meet two terminal cisternae of sarcoplasmic reticulum to form triads , which carry excitation inside and release calcium."],"dp":[]},"histo1-muscle:e3":{"s":2,"u":["Sarcomere = Z to Z; I band actin only, A band myosin length, H zone myosin only.","The I band (light) contains only thin actin filaments and is bisected by the Z line; the A band (dark) is the length of the thick myosin filaments; the H zone in the middle of the A band has myosin only, with the M line at its centre.","In contraction the filaments slide : the sarcomere, I band and H zone shorten while the A band keeps its length."],"dp":[]},"histo1-muscle:e4":{"s":2,"u":["Contraction: I band and H zone shorten; A band unchanged.","In contraction the filaments slide : the sarcomere, I band and H zone shorten while the A band keeps its length.","The I band (light) contains only thin actin filaments and is bisected by the Z line; the A band (dark) is the length of the thick myosin filaments; the H zone in the middle of the A band has myosin only, with the M line at its centre."],"dp":[]},"histo1-muscle:e6":{"s":3,"u":["Cardiac: branched, 1-2 central nuclei, intercalated discs (gap junctions + desmosomes).","Cells join end to end at intercalated discs , step-like junctions with gap junctions (electrical coupling so the heart contracts as a unit) and desmosomes / fascia adherens (mechanical anchorage).","Cardiac muscle : striated, branched cells with one (sometimes two) central nucleus ; involuntary ."],"dp":[{"h":"Why the heart cannot afford a scar in the wrong place","t":"Cardiomyocytes stop dividing soon after birth, so dead muscle is replaced by collagen. A scar does not contract, and it has no gap junctions, so the electrical wave that normally spreads cell to cell through intercalated discs must travel around it. Slow, detouring conduction at the border of a scar sets up re-entry circuits , the mechanism behind many ventricular arrhythmias after a heart attack. The same gap junctions that make the heart a coordinated pump explain why a scar is dangerous. Source: the course summary on cardiac muscle and intercalated discs."}]},"histo1-muscle:e7":{"s":3,"u":["Smooth: fusiform, one central nucleus, no striations, dense bodies.","Smooth muscle : spindle-shaped (fusiform) cells with one central nucleus , no striations because actin and myosin are not arranged in sarcomeres but anchored to dense bodies ; involuntary ; linked by gap junctions; can divide and regenerate well.","Cardiac muscle : striated, branched cells with one (sometimes two) central nucleus ; involuntary ."],"dp":[]},"histo1-muscle:e8":{"s":3,"u":["Regeneration: skeletal via satellite cells; cardiac very poor (scar); smooth good."],"dp":[]}},"meta":{"o1gnww":{"a":"recall","vg":"histo1-muscle:e1/recall/1"},"qere58":{"a":"recall","vg":"histo1-muscle:e6/recall/1"},"t9ht2o":{"a":"recall","vg":"histo1-muscle:e7/recall/1"},"1eth56b":{"a":"recall","vg":"histo1-muscle:e4/recall/1"},"11x9ydm":{"a":"recall","vg":"histo1-muscle:e4/recall/1"},"tvayrb":{"a":"relationship","vg":"histo1-muscle:e3/relationship/1"},"1phwcsl":{"a":"recall","vg":"histo1-muscle:e2/recall/1"},"k5jx55":{"a":"recall","vg":"histo1-muscle:e6/recall/2"},"imsbr0":{"a":"recall","vg":"histo1-muscle:e8/recall/1"},"w9y29f":{"a":"recall","vg":"histo1-muscle:e8/recall/2"},"h1hn9o":{"a":"recall","vg":"histo1-muscle:e7/recall/2"},"1i4ujp2":{"a":"recall","vg":"histo1-muscle:e5/recall/1"},"1oixcky":{"a":"recall","vg":"histo1-muscle:e1/recall/2"},"f2s6wy":{"a":"recall","vg":"histo1-muscle:e5/recall/2"},"41u591":{"a":"recall","vg":"histo1-muscle:e7/recall/2"}},"explRev":"75ae415ce883"};
